import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools.md","filePath":"reference/tools.md","lastUpdated":1786904142000}`),a={name:`reference/tools.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to “Tools”">​</a></h1><p>Fourteen tools. With <code>OPENGIST_READ_ONLY=true</code> only the eight reading tools are registered — the writing ones do not appear in <code>tools/list</code> at all.</p><nav class="table-of-contents"><ul><li><a href="#reading">Reading</a><ul><li><a href="#list-gists">list_gists</a></li><li><a href="#get-gist">get_gist</a></li><li><a href="#get-gist-file">get_gist_file</a></li><li><a href="#list-gist-commits">list_gist_commits</a></li><li><a href="#list-gist-forks">list_gist_forks</a></li><li><a href="#search-gists">search_gists</a></li><li><a href="#get-user">get_user</a></li><li><a href="#check-gist-like">check_gist_like</a></li></ul></li><li><a href="#writing">Writing</a><ul><li><a href="#create-gist">create_gist</a></li><li><a href="#update-gist">update_gist</a></li><li><a href="#delete-gist-files">delete_gist_files</a></li><li><a href="#delete-gist">delete_gist</a></li><li><a href="#fork-gist">fork_gist</a></li><li><a href="#set-gist-like">set_gist_like</a></li></ul></li></ul></nav><h2 id="reading" tabindex="-1">Reading <a class="header-anchor" href="#reading" aria-label="Permalink to “Reading”">​</a></h2><h3 id="list-gists" tabindex="-1"><code>list_gists</code> <a class="header-anchor" href="#list-gists" aria-label="Permalink to “list_gists”">​</a></h3><p>Lists gist summaries — no file contents. Use <code>get_gist</code> for those.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>scope</code></td><td>enum</td><td><code>mine</code></td><td><code>mine</code>, <code>public</code>, <code>liked</code>, <code>forked</code></td></tr><tr><td><code>username</code></td><td>string</td><td>—</td><td>Narrows the scope to that user instead of the token owner</td></tr><tr><td><code>since</code></td><td>string</td><td>—</td><td>RFC 3339 timestamp; only gists updated after it</td></tr><tr><td><code>page</code></td><td>number</td><td><code>1</code></td><td></td></tr><tr><td><code>perPage</code></td><td>number</td><td><code>30</code></td><td></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Missing private gists mean a missing scope</p><p>If gists you can see in the browser are absent here, the token lacks <code>gist:read</code>. The API does not fail in that case — it silently returns only the public ones.</p></div><h3 id="get-gist" tabindex="-1"><code>get_gist</code> <a class="header-anchor" href="#get-gist" aria-label="Permalink to “get_gist”">​</a></h3><p>One gist including its file contents, optionally at an older revision.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>gistId</code></td><td>string</td><td>required</td><td></td></tr><tr><td><code>sha</code></td><td>string</td><td>—</td><td>Read the gist as of this commit</td></tr><tr><td><code>includeContent</code></td><td>boolean</td><td><code>true</code></td><td></td></tr><tr><td><code>maxFileBytes</code></td><td>number</td><td></td><td>Per-file cap</td></tr><tr><td><code>maxTotalBytes</code></td><td>number</td><td></td><td>Cap across all files of the call</td></tr><tr><td><code>includeCommits</code></td><td>boolean</td><td><code>false</code></td><td></td></tr><tr><td><code>maxCommits</code></td><td>number</td><td></td><td></td></tr><tr><td><code>includeForks</code></td><td>boolean</td><td><code>false</code></td><td></td></tr><tr><td><code>includeCloneUrls</code></td><td>boolean</td><td><code>false</code></td><td><code>clone_url</code> and <code>ssh_url</code>, for handing to git</td></tr></tbody></table><p>Truncated or omitted content always produces a note naming the <code>get_gist_file</code> call that returns the rest. Binary files are reported as omitted rather than dumped.</p><p>A 404 means the gist does not exist <strong>or</strong> is invisible to this token. It does not mean it was deleted.</p><h3 id="get-gist-file" tabindex="-1"><code>get_gist_file</code> <a class="header-anchor" href="#get-gist-file" aria-label="Permalink to “get_gist_file”">​</a></h3><p>The raw content of one file, optionally at a revision and from a byte offset. This is what you use to page through a file <code>get_gist</code> truncated.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>gistId</code></td><td>string</td><td>required</td></tr><tr><td><code>filename</code></td><td>string</td><td>required</td></tr><tr><td><code>sha</code></td><td>string</td><td>—</td></tr><tr><td><code>offset</code></td><td>number</td><td><code>0</code></td></tr><tr><td><code>maxBytes</code></td><td>number</td><td></td></tr></tbody></table><h3 id="list-gist-commits" tabindex="-1"><code>list_gist_commits</code> <a class="header-anchor" href="#list-gist-commits" aria-label="Permalink to “list_gist_commits”">​</a></h3><p>Commit history, newest first. Feed a SHA from here into <code>get_gist</code> or <code>get_gist_file</code> to read an older revision.</p><p>Parameters: <code>gistId</code> (required), <code>page</code>, <code>perPage</code>.</p><h3 id="list-gist-forks" tabindex="-1"><code>list_gist_forks</code> <a class="header-anchor" href="#list-gist-forks" aria-label="Permalink to “list_gist_forks”">​</a></h3><p>The gists forked from this one. Parameters: <code>gistId</code> (required), <code>page</code>, <code>perPage</code>.</p><h3 id="search-gists" tabindex="-1"><code>search_gists</code> <a class="header-anchor" href="#search-gists" aria-label="Permalink to “search_gists”">​</a></h3><p>Opengist has no search endpoint, so this pages through the list endpoints and filters client-side. It is bounded by design and the result always says how much it scanned and whether it was cut short.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>required</td><td></td></tr><tr><td><code>in</code></td><td>string[]</td><td>title, description, topics, owner</td><td>Which fields to match</td></tr><tr><td><code>scope</code></td><td>enum</td><td><code>mine</code></td><td>Same scopes as <code>list_gists</code></td></tr><tr><td><code>username</code></td><td>string</td><td>—</td><td></td></tr><tr><td><code>visibility</code></td><td>enum</td><td>—</td><td>Filter the results</td></tr><tr><td><code>archived</code></td><td>boolean</td><td>—</td><td></td></tr><tr><td><code>since</code></td><td>string</td><td>—</td><td></td></tr><tr><td><code>limit</code></td><td>number</td><td></td><td>Stop after this many matches</td></tr><tr><td><code>maxPages</code></td><td>number</td><td></td><td>Stop after this many pages scanned</td></tr></tbody></table><p>Searching <em>inside</em> file contents is not supported — it would mean downloading every file of every gist. Narrow the field here, then read the candidates with <code>get_gist</code>.</p><h3 id="get-user" tabindex="-1"><code>get_user</code> <a class="header-anchor" href="#get-user" aria-label="Permalink to “get_user”">​</a></h3><p>Without arguments: the account the token belongs to, including its email address. With <code>username</code> or <code>userId</code>: that user&#39;s public profile.</p><p>The returned fields are an allowlist (<code>id</code>, <code>username</code>, <code>login</code>, <code>type</code>, <code>avatarUrl</code>, <code>email</code>, <code>createdAt</code>), not a pass-through, so anything Opengist adds to this endpoint later does not reach the model automatically.</p><h3 id="check-gist-like" tabindex="-1"><code>check_gist_like</code> <a class="header-anchor" href="#check-gist-like" aria-label="Permalink to “check_gist_like”">​</a></h3><p>Whether the token owner has liked a gist. Distinguishes &quot;not liked&quot; from &quot;not visible to you&quot;. Parameter: <code>gistId</code>.</p><h2 id="writing" tabindex="-1">Writing <a class="header-anchor" href="#writing" aria-label="Permalink to “Writing”">​</a></h2><h3 id="create-gist" tabindex="-1"><code>create_gist</code> <a class="header-anchor" href="#create-gist" aria-label="Permalink to “create_gist”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>files</code></td><td>array</td><td>required</td><td><code>{ filename, content }</code>, 1–50, content must be non-empty</td></tr><tr><td><code>visibility</code></td><td>enum</td><td>required</td><td><code>private</code>, <code>unlisted</code>, <code>public</code> — never implicit</td></tr><tr><td><code>title</code></td><td>string</td><td>—</td><td>Defaults to the first filename</td></tr><tr><td><code>description</code></td><td>string</td><td>—</td><td></td></tr><tr><td><code>expire</code></td><td>enum</td><td>—</td><td><code>never</code>, <code>1hour</code>, <code>12hours</code>, <code>1day</code>, <code>7days</code>, <code>15days</code></td></tr><tr><td><code>expiresAt</code></td><td>string</td><td>—</td><td>RFC 3339; mutually exclusive with <code>expire</code></td></tr><tr><td><code>confirmToken</code></td><td>string</td><td>—</td><td>Required for <code>public</code> and <code>unlisted</code> — see below</td></tr></tbody></table><p>Content must be non-empty: Opengist silently drops files without content on create, so an empty one would vanish rather than fail.</p><div class="danger custom-block"><p class="custom-block-title">Publishing needs confirmation</p><p><code>visibility: &quot;public&quot;</code> or <code>&quot;unlisted&quot;</code> is a disclosure event. The first call is refused and returns a single-use token; call again within five minutes with <code>confirmToken</code> and otherwise identical arguments. The token is bound to the exact content, so it cannot be replayed with a different or an extra file attached.</p></div><p>Expiry can only be set at creation. There is no way to change it afterwards.</p><h3 id="update-gist" tabindex="-1"><code>update_gist</code> <a class="header-anchor" href="#update-gist" aria-label="Permalink to “update_gist”">​</a></h3><p>Changes metadata and/or writes and renames files. <strong>Files you do not list are left untouched</strong> — never list a file just to preserve it.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>gistId</code></td><td>string</td><td>required</td><td></td></tr><tr><td><code>title</code></td><td>string</td><td>—</td><td></td></tr><tr><td><code>description</code></td><td>string</td><td>—</td><td></td></tr><tr><td><code>visibility</code></td><td>enum</td><td>—</td><td></td></tr><tr><td><code>fileOps</code></td><td>array</td><td>—</td><td><code>write</code> and <code>rename</code> operations, see below</td></tr><tr><td><code>allowCreate</code></td><td>boolean</td><td><code>false</code></td><td>Permit a <code>write</code> to a filename that does not exist</td></tr><tr><td><code>confirmToken</code></td><td>string</td><td>—</td><td></td></tr></tbody></table><p><code>fileOps</code> entries are one of:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">{ </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;op&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;write&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;filename&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;notes.md&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;content&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;…&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">{ </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;op&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;rename&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;filename&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;old.md&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;newFilename&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;new.md&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;content&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;…&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> }</span></span></code></pre></div><p><code>content</code> on a rename is optional; without it the file keeps its content under the new name.</p><p>This tool <strong>cannot delete a file</strong> — that is <code>delete_gist_files</code>. The Opengist API deletes a file whose entry is <code>null</code> or carries neither <code>content</code> nor <code>filename</code>, which is exactly the shape a carelessly built object has, so the raw file map is never exposed as an input and every payload is checked before it is sent.</p><p>A write to a filename that does not exist is refused unless <code>allowCreate</code> is set, and the refusal names a case-insensitive near match (<code>readme.md</code> vs <code>README.md</code>) so a typo does not quietly become a second file.</p><p>A confirmation token is required when the call <strong>widens</strong> the visibility, and when it writes files into a gist that is already <code>public</code> or <code>unlisted</code>. It is not required when the same call makes the gist private, or for metadata-only changes.</p><p>The response reports <code>previousRevision</code>, so the state before the change stays retrievable with <code>get_gist</code> and a <code>sha</code>.</p><h3 id="delete-gist-files" tabindex="-1"><code>delete_gist_files</code> <a class="header-anchor" href="#delete-gist-files" aria-label="Permalink to “delete_gist_files”">​</a></h3><p>Deletes files from a gist. They disappear from the current revision; older revisions keep them in git history.</p><p>Parameters: <code>gistId</code>, <code>filenames</code> (1–50), <code>confirmToken</code>.</p><p>The token is bound to the exact set of filenames — a confirmation for one file cannot be replayed to delete another. Deleting <em>every</em> file is refused; use <code>delete_gist</code>.</p><h3 id="delete-gist" tabindex="-1"><code>delete_gist</code> <a class="header-anchor" href="#delete-gist" aria-label="Permalink to “delete_gist”">​</a></h3><p>Permanently deletes a gist: the git repository with every revision and the database row. Irreversible.</p><p>Parameters: <code>gistId</code>, <code>confirmToken</code>.</p><p>The refusal quotes server-side metadata only — visibility, file count, fork count, like count, creation date — never the title or description.</p><h3 id="fork-gist" tabindex="-1"><code>fork_gist</code> <a class="header-anchor" href="#fork-gist" aria-label="Permalink to “fork_gist”">​</a></h3><p>Forks someone else&#39;s gist into your account. Forking one you already forked returns the existing fork rather than creating a second one, and the result says which happened. Parameter: <code>gistId</code>.</p><h3 id="set-gist-like" tabindex="-1"><code>set_gist_like</code> <a class="header-anchor" href="#set-gist-like" aria-label="Permalink to “set_gist_like”">​</a></h3><p>Likes or unlikes a gist. Idempotent: the current state is read first and the gist is only toggled when it differs, so calling it twice with the same value does not undo itself. Requires <code>user:write</code> on the token.</p><p>Parameters: <code>gistId</code>, <code>liked</code> (boolean, required).</p>`,59)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};